const DAY = 86400000;
function branchHousekeeping(input) {
  const now = Date.parse(input.now);
  if (!Number.isFinite(now)) throw Error('Invalid clock');
  const cutoff = now - 30 * DAY;
  const findings = [], clean = [], errors = [];
  let scanned = 0, total = 0;
  const excluded = new Set(input.config.excluded_repos || []);
  for (const name of [...new Set(input.config.repos)]) {
    if (excluded.has(name)) continue;
    const repo = input.repositories[name];
    if (!repo || repo.error) { errors.push({ repository: name, reason: repo?.error || 'Missing captured state' }); continue; }
    if (repo.archived) continue;
    scanned++;
    total += repo.branches.filter(b => b.name !== repo.default_branch).length;
    let count = 0;
    const errorsBefore = errors.length;
    for (const branch of repo.branches) {
      if (branch.name === repo.default_branch || ['main', 'master', 'develop'].includes(branch.name) || branch.name.startsWith('release/')) continue;
      const date = Date.parse(branch.last_commit_at);
      if (!Number.isFinite(date) || typeof branch.merged !== 'boolean') { errors.push({ repository: name, branch: branch.name, reason: 'Missing or invalid commit/comparison state' }); continue; }
      if (!branch.merged && date >= cutoff) continue;
      findings.push({ repository: name, branch: branch.name, category: branch.merged ? 'merged' : 'stale', last_commit_at: branch.last_commit_at, author: branch.author, behind: branch.behind, open_prs: branch.open_prs || [], recommendation: branch.merged ? 'Recommend deletion' : 'Review before deletion' });
      count++;
    }
    if (!count && errors.length === errorsBefore) clean.push(name);
  }
  const counts = { repositories: scanned, non_default_branches: total, merged: findings.filter(f => f.category === 'merged').length, stale: findings.filter(f => f.category === 'stale').length };
  const section = (kind, heading) => heading + '\n\n' + findings.filter(f => f.category === kind).map(f => `| ${f.repository} | \`${f.branch}\` | ${f.last_commit_at} | @${f.author} | ${f.behind ?? 'unknown'} | ${f.open_prs.map(n => '#' + n).join(', ') || 'N/A'} |`).join('\n');
  const body = `### [Branch Cleanup] Weekly Report — ${new Date(now).toISOString().slice(0, 10)}\n\n**Scanned:** ${scanned} repositories | **Run:** ${input.run_id}\n\n#### Summary\n\n| Metric | Count |\n| --- | ---: |\n| Repos scanned | ${scanned} |\n| Total branches (non-default) | ${total} |\n| Merged branches pending deletion | ${counts.merged} |\n| Stale unmerged branches | ${counts.stale} |\n\n` + section('merged', '#### Merged Branches (Safe to Delete)\n\n| Repository | Branch | Last Commit | Author | Behind | Open PR |\n| --- | --- | --- | --- | --- | --- |') + '\n\n' + section('stale', '#### Stale Unmerged Branches (Review Required)\n\n| Repository | Branch | Last Commit | Author | Behind | Open PR |\n| --- | --- | --- | --- | --- | --- |') + '\n\n#### Clean Repositories\n\n' + clean.join(', ') + (errors.length ? '\n\nErrors: ' + errors.map(e => `${e.repository}${e.branch ? '/' + e.branch : ''}: ${e.reason}`).join('; ') : '') + '\n\n*Generated by housekeeping-branches workflow — ' + input.run_url + '*';
  return { actions: [{ kind: 'create_issue', title: '[Branch Cleanup] Weekly Report — ' + new Date(now).toISOString().slice(0, 10), labels: ['gpm/report'], body }], findings, counts, errors, clean };
}


module.exports = {branchHousekeeping};
